def maximum_xor_pair(nums):
    WIDTH = 32
    root = {}
    for num in nums:
        node = root
        for bit in range(WIDTH - 1, -1, -1):
            b = (num >> bit) & 1
            if b not in node:
                node[b] = {}
            node = node[b]
    best = 0
    for num in nums:
        node = root
        cur = 0
        for bit in range(WIDTH - 1, -1, -1):
            b = (num >> bit) & 1
            want = 1 - b
            if want in node:
                cur |= (1 << bit)
                node = node[want]
            else:
                node = node[b]
        if cur > best:
            best = cur
    return best
